'use strict';
const pharmacyPreviousRender=render,pharmacyPreviousCard=card,pharmacyPreviousShop=shop;let compareQuery='',medQuery='',rxFileData=null;
const localReceipts=key=>{const data=read(key,[]);return Array.isArray(data)?data:[]};let rxReceipts=localReceipts('rx-receipts'),consultReceipts=localReceipts('consult-receipts');
const pmoney=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const pharmacyNotice='<div class="pharmacy-disclaimer"><span>DEMO PRICES & STOCK</span><p>These are sample prices, not live market quotes. Matching data supports comparison; a pharmacist or prescriber must assess clinical suitability. Never switch prescribed medicine yourself.</p></div>';
function medCard(p){return `<article class="medicine-card product-card"><div class="medicine-tags"><span class="pill ${p.prescription?'rx':'otc'}">${p.prescription?'Rx · Team review':'Wellness / OTC demo'}</span><button class="heart ${favourites.includes(p.id)?'saved':''}" data-action="favourite" data-id="${p.id}" aria-label="Save ${esc(p.name)}">♡</button></div><a class="product-image" href="#/product/${p.id}"><img src="${esc(p.image)}" alt="Illustrative demo packaging for ${esc(p.name)}" loading="lazy"></a><span class="product-category">${esc(p.brand)}</span><a href="#/product/${p.id}"><h3>${esc(p.name)}</h3></a><p class="medicine-composition">${esc(p.ingredient||p.category)} ${esc(p.strength||'')}</p><p class="pack">${esc(p.pack)} · ${p.stock?'Sample stock available':'Out of sample stock'}</p><div class="medicine-price"><b>${money(p.price)}</b><small>Sample pack price</small><span>${pmoney(PharmacyCore.unitPrice(p))} / unit</span></div><div class="medicine-actions">${p.prescription?`<a class="btn primary" href="#/prescription?medicine=${p.id}">Get Rx quotation ↗</a>`:`<button class="btn primary" data-action="add" data-id="${p.id}" ${!p.stock?'disabled':''}>${p.stock?'Add to basket +':'Unavailable'}</button>`}${p.ingredient?`<a class="compare-link" href="#/compare?medicine=${p.id}">Compare prices & options <span>⇄</span></a>`:''}</div></article>`}
card=function(p){return p.medicine?medCard(p):pharmacyPreviousCard(p)};
function searchMedicine(params){const query=(params.get('q')||'').toLowerCase(),type=params.get('type')||'all',sort=params.get('sort')||'featured',inStock=params.get('stock')==='1';let list=Store.state.products.filter(p=>p.active&&p.medicine&&(!inStock||p.stock>0)&&(type==='all'||(type==='rx'?p.prescription:!p.prescription))&&[p.name,p.brand,p.ingredient,p.strength,p.manufacturer].join(' ').toLowerCase().includes(query));if(sort==='unit')list.sort((a,b)=>PharmacyCore.unitPrice(a)-PharmacyCore.unitPrice(b));if(sort==='low')list.sort((a,b)=>a.price-b.price);return list}
function medCatalogue(params){const list=searchMedicine(params);return `${pageTitle(esc(Store.state.pages.medicinesTitle),'Search by medicine, ingredient or brand. Explore sample stock, packs, offers and prescription quotation options.')}<section class="pharmacy-search-panel"><form id="medicine-search" class="pharmacy-search"><span>⌕</span><input type="search" name="q" value="${esc(params.get('q')||'')}" placeholder="Try Pantop, paracetamol, telmisartan…" aria-label="Search medicine, brand or ingredient"><button class="btn primary">Find medicine ↗</button></form><div class="pharmacy-filter-row"><div class="chips">${[['all','All medicines'],['otc','OTC / everyday'],['rx','Prescription medicines']].map(([id,label])=>`<button class="chip ${id===(params.get('type')||'all')?'active':''}" data-pharma="medicine-filter" data-filter="type" data-value="${id}">${label}</button>`).join('')}</div><label class="inline-check"><input id="medicine-stock" type="checkbox" ${params.get('stock')==='1'?'checked':''}> Available sample stock</label><select id="medicine-sort" aria-label="Sort medicines"><option value="featured">Recommended browsing</option><option value="unit" ${params.get('sort')==='unit'?'selected':''}>Lowest price / unit</option><option value="low" ${params.get('sort')==='low'?'selected':''}>Lowest pack price</option></select></div></section><div class="collection-caption"><b>${list.length} demo medicines</b><a href="#/compare">Open the comparison portal ⇄</a></div><div class="medicine-grid">${list.length?list.map(medCard).join(''):'<div class="empty"><h2>No matching medicine in this sample catalogue.</h2><p>Try another name, or send your medicine list for a team quotation.</p><a class="btn primary" href="#/prescription">Request a quotation</a></div>'}</div>${pharmacyNotice}<section class="section"><div class="service-mini-grid"><a href="#/shop?category=Vitamins"><b>Vitamins & nutraceuticals</b><span>Explore everyday wellness ↗</span></a><a href="#/shop"><b>Personal care & devices</b><span>Shop your family essentials ↗</span></a><a href="#/consult"><b>Talk to a doctor</b><span>Request a consultation ↗</span></a></div></section></div>`}
function comparisonTable(rows,base,lowest,compatible=true){return `<div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>Medicine / brand</th><th>Composition & presentation</th><th>Pack</th><th>Sample pack price</th><th>Sample unit price</th><th>Availability & next step</th></tr></thead><tbody>${rows.map(p=>`<tr class="${compatible&&lowest?.id===p.id?'lowest-row':''}"><td><div class="comparison-product"><img src="${esc(p.image)}" alt="Demo pack illustration"><div><a href="#/product/${p.id}"><b>${esc(p.name)}</b></a><small>${esc(p.manufacturer)}</small>${lowest?.id===p.id&&compatible?'<span class="lowest-badge">Lowest available demo unit price</span>':''}</div></div></td><td><b>${esc(p.ingredient)} ${esc(p.strength)}</b><small>${esc(p.dosageForm)} · ${esc(p.release)}<br>${esc(p.variant)}</small><span class="match-tag ${compatible?'':'different'}">${compatible?'Matching listed metadata':'Different strength / formulation'}</span></td><td>${p.packUnits} units</td><td><b>${money(p.price)}</b><small>Illustrative price</small></td><td><strong>${pmoney(PharmacyCore.unitPrice(p))}</strong><small>per unit</small>${compatible&&p.id!==base.id&&PharmacyCore.unitPrice(p)<PharmacyCore.unitPrice(base)?`<span class="saving-chip">${Math.round((1-PharmacyCore.unitPrice(p)/PharmacyCore.unitPrice(base))*100)}% lower sample unit price</span>`:''}</td><td><small class="${p.stock?'green-text':''}">${p.stock?'Sample stock available':'Out of sample stock'}</small>${p.prescription?`<a class="btn primary" href="#/prescription?medicine=${p.id}">Request Rx quote</a>`:`<a class="btn" href="#/product/${p.id}">View product ↗</a>`}</td></tr>`).join('')}</tbody></table></div>`}
function comparePage(params){const medicines=Store.state.products.filter(p=>p.active&&p.ingredient),id=params.get('medicine')||medicines[0]?.id,result=PharmacyCore.compare(Store.state,id),q=params.get('q')||'';const options=medicines.filter(p=>[p.name,p.brand,p.ingredient].join(' ').toLowerCase().includes(q.toLowerCase()));return `${pageTitle(esc(Store.state.pages.compareTitle),esc(Store.state.pages.compareIntro))}<section class="comparison-controls"><form id="comparison-search" class="pharmacy-search"><span>⌕</span><input type="search" name="q" placeholder="Find a medicine, brand or ingredient" value="${esc(q)}" aria-label="Find comparison medicine"><button class="btn primary">Find</button></form><label class="field">Choose the medicine you want to compare<select id="comparison-medicine">${options.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)} · ${esc(p.strength)}</option>`).join('')}</select></label></section>${!options.length?'<div class="notice">No matching name in this sample catalogue. Try another search.</div>':''}${result.base?`<section class="comparison-summary"><div><span class="eyebrow">Your comparison</span><h2>${esc(result.base.name)}</h2><p>${esc(result.base.ingredient)} · ${esc(result.base.strength)} · ${esc(result.base.release)}</p><span>${result.matches.length} matching-metadata ${result.matches.length===1?'pack':'packs'} · Pack sizes normalised per unit</span></div><div class="unit-highlight"><small>Lowest available demo price</small><strong>${result.lowest?pmoney(PharmacyCore.unitPrice(result.lowest)):'Unavailable'}</strong><span>per unit · price-based, not clinical advice</span></div></section>${comparisonTable(result.matches,result.base,result.lowest)}${result.nearby.length?`<section class="section"><div class="section-heading"><div><h2>Related names. Important differences.</h2><p>These do not meet all comparison fields. They are not ranked as interchangeable alternatives.</p></div></div>${comparisonTable(result.nearby,result.base,null,false)}</section>`:''}<div class="notice">The “lowest” label considers available sample stock and price per unit among matching ingredient, strength, dosage form, release, route and formulation fields. It does not establish bioequivalence, clinical suitability or a prescription substitution.</div>${result.base.source?`<p class="source-note">Brand/composition reference: <a href="${esc(result.base.source)}" target="_blank" rel="noopener noreferrer">Manufacturer information ↗</a>. All prices, offers, stock and generic-demo packs here are illustrative.</p>`:''}`:'<div class="empty"><h2>Select a medicine from the catalogue.</h2></div>'}${pharmacyNotice}</div>`}
function offersPage(){return `${pageTitle('A little more value for your care.','Explore the demo’s offers and comparison tools. Terms and availability are controlled by admin.')}<div class="offer-grid">${Store.state.offers.filter(o=>o.active).map(o=>`<article class="offer-card"><img src="${esc(o.image)}" alt="${esc(o.title)}"><div><span class="eyebrow">Demo offer</span><h2>${esc(o.title)}</h2><p>${esc(o.description)}</p><div class="buttons">${o.code?`<button class="coupon-copy" data-pharma="copy-coupon" data-code="${esc(o.code)}">${esc(o.code)} &nbsp; ⧉</button>`:''}<a class="btn primary" href="${esc(o.link)}">Explore offer ↗</a></div></div></article>`).join('')}</div><div class="notice">Only active, valid coupons meeting the minimum order apply at demo checkout. Coupon discounts do not apply to the separately reviewed prescription quote.</div><div class="section-heading" style="margin-top:30px"><h2>Everyday essentials with sample offers.</h2></div><div class="product-grid">${Store.state.products.filter(p=>p.active&&!p.prescription&&p.stock>0).slice(0,4).map(card).join('')}</div></div>`}
function prescriptionPage(params){const selected=Store.state.products.find(p=>p.id===params.get('medicine'));return `${pageTitle('Your prescription. A personal quotation.','Send a sample prescription for your team to review. Review, clarification and quotation happen in the admin workspace.')}<div class="rx-layout"><form class="panel" id="pharmacy-rx-form"><span class="eyebrow">Prescription request</span><h2>A clear next step for your medicines.</h2><div class="notice">Demo workflow: upload a sample document only. No automated authenticity decision, clinical review, real dispensing or payment takes place.</div><label class="field">Demo patient alias<input name="patientAlias" required maxlength="100" placeholder="e.g. Sample Customer"></label><label class="field">Medicines or notes (optional)<textarea name="notes" maxlength="2000" placeholder="Tell the team which medicines to quote">${selected?esc('Please review and quote: '+selected.name):''}</textarea></label><label class="upload-zone"><b>▤ &nbsp; Upload sample prescription</b><span>JPG, PNG or PDF · Maximum 2 MB</span><input id="rx-sample-file" type="file" accept="image/jpeg,image/png,application/pdf" required><p id="rx-file-note" class="small">No file selected</p><img id="rx-sample-preview" alt="Sample prescription preview" hidden></label><label class="checkbox"><input name="sampleConfirmed" type="checkbox" required><span>I am authorised to share this sample document. I understand this is a demo and team review is required.</span></label><button class="btn primary block">Submit for team review ↗</button><p id="rx-submit-message" class="small" role="status"></p></form><div><section class="panel"><h2>Your review journey.</h2>${[['01','Submit your document','A private request is created. The admin team can view the sample document and notes.'],['02','Team checks the prescription','The team records prescriber, date, legibility, suitability and authenticity-review notes. No software can guarantee that a document is genuine.'],['03','Receive an itemised quotation','An approved request can be quoted with quantities, prices and an expiry. You can accept the quote from My Care.'],['04','Review the order','Accepting an in-stock, unexpired demo quote creates an order with no payment or dispatch.']].map(([n,t,p])=>`<div class="rx-step"><span>${n}</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</section><div class="notice green"><b>Already submitted?</b> Keep this browser’s request receipt to track its status and quotation.</div><a class="btn block" href="#/my-care">Open My Care & quotations ↗</a>${Store.state.settings.whatsappNumber?`<a class="text-link" href="https://wa.me/${esc(Store.state.settings.whatsappNumber)}" target="_blank" rel="noopener">Optional WhatsApp enquiry ↗</a>`:''}</div></div></div>`}
function consultationPage(){const banner=Store.state.banners.find(b=>b.active&&b.placement==='consult');return `${pageTitle(esc(Store.state.pages.consultTitle),'Request a consultation and let your team confirm the clinician, time and next steps. This demo does not provide medical consultations.')}<section class="consult-hero promo-poster"><img src="${esc(banner?.image||'assets/consultation-landscape.webp')}" alt="Illustrative online consultation scene"><div class="poster-copy"><span class="eyebrow">Care starts with listening</span><h2>${esc(banner?.title||'Questions deserve a thoughtful conversation.')}</h2><p>${esc(banner?.subtitle||'Choose a service. Send a request. Your team follows up.')}</p><a class="btn primary" href="#/consult" data-pharma="consult-scroll">Explore consultations ↗</a></div></section><div id="consult-services" class="consult-grid">${Store.state.consultations.filter(c=>c.active).map(c=>`<article class="consult-card">${c.image?`<img class="consult-service-image" src="${esc(c.image)}" alt="Illustrative consultation scene" loading="lazy">`: ''}<div class="specialty-icon">${c.specialty==='Dermatology'?'✧':c.specialty==='Nutrition'?'❧':'✚'}</div><span class="product-category">${esc(c.specialty)}</span><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><div class="consult-meta"><span>◷ ${c.duration} minutes</span><span>◎ ${esc(c.languages)}</span></div><div class="consult-price"><b>${money(c.fee)}</b><small>Sample fee · nothing charged</small></div><button class="btn primary block" data-pharma="book-consult" data-id="${esc(c.id)}">Request consultation ↗</button><small>No clinician assigned until team confirmation</small></article>`).join('')}</div><div class="notice">For urgent symptoms or emergencies, use local emergency services. This request form is not monitored as an emergency service.</div><a class="text-link" href="#/my-care">View your consultation requests ↗</a></div>`}
function consultModal(id){const c=Store.state.consultations.find(c=>c.id===id&&c.active);if(!c)return;modal(`<h2>${esc(c.name)}</h2><p>${money(c.fee)} sample fee · No payment or appointment is confirmed now.</p><form id="consult-request-form" data-service="${esc(id)}"><label class="field">Demo patient alias<input name="patientAlias" required maxlength="100" placeholder="Sample Customer"></label><div class="form-grid"><label class="field">Preferred date<input type="date" name="date" required min="${new Date().toISOString().slice(0,10)}"></label><label class="field">Preferred time (India time)<select name="time"><option>09:00</option><option>11:00</option><option>14:00</option><option>16:00</option></select></label></div><label class="field">Notes (optional)<textarea name="notes" maxlength="2000" placeholder="Use sample details only"></textarea></label><label class="checkbox"><input name="sampleConfirmed" type="checkbox" required><span>I understand this creates a demo request and the team must confirm the clinician and time.</span></label><button class="btn primary block">Send consultation request ↗</button></form>`)}
function myCarePage(){return `${pageTitle('Your requests & quotations','Track your prescription review, quotation and consultation requests in this browser.')}<div class="care-tabs"><a class="chip" href="#/account">Demo profile</a><a class="chip active" href="#/my-care">Requests & quotations</a><a class="chip" href="#/account?tab=orders">Order history</a><button class="chip" data-pharma="refresh-care">↻ Refresh status</button></div><div id="my-care-content"><p class="notice">Loading your request receipts…</p></div><div class="notice">Keep this browser’s receipts. In Node mode, each request is protected by a private token. Customer authentication and cross-device recovery will be added with the database setup.</div></div>`}
async function loadMyCare(){const target=document.getElementById('my-care-content');if(!target)return;const rx=await Promise.all(rxReceipts.map(async receipt=>{try{return {...await Store.prescriptionStatus(receipt),receipt}}catch{return {id:receipt.id,status:'Unavailable',lines:[]}}})),appointments=await Promise.all(consultReceipts.map(async receipt=>{try{return await Store.consultationStatus(receipt)}catch{return {id:receipt.id,status:'Unavailable'}}}));if(!document.getElementById('my-care-content'))return;document.getElementById('my-care-content').innerHTML=`<section class="section"><div class="section-heading"><h2>Prescription requests & quotations.</h2><a class="text-link" href="#/prescription">New request +</a></div>${rx.length?rx.map(r=>`<article class="care-request panel"><div class="request-heading"><div><span class="eyebrow">${esc(r.id)}</span><h3>${esc(r.patientAlias||'Prescription enquiry')}</h3></div><span class="pill">${esc(r.status)}</span></div><p>${r.reviewRecorded||r.review?.authenticity==='Manual review recorded'?'Manual review recorded by the demo team.':'Awaiting review or clarification by the team.'}</p>${r.quoteNote?`<div class="notice">${esc(r.quoteNote)}</div>`:''}${r.lines?.length?`<div class="comparison-scroll"><table class="quote-table"><thead><tr><th>Item</th><th>Qty</th><th>Price / pack</th><th>Total</th></tr></thead><tbody>${r.lines.map(l=>`<tr><td>${esc(l.name||Store.state.products.find(p=>p.id===l.id)?.name||l.id)}</td><td>${l.qty}</td><td>${pmoney(l.unitPrice)}</td><td>${pmoney(l.unitPrice*l.qty)}</td></tr>`).join('')}</tbody></table></div><div class="quote-grand-total"><span>Quoted total</span><b>${pmoney(r.total??PharmacyCore.quoteTotal(r))}</b></div><p class="small">Valid until ${esc(r.quoteExpiry)}. No payment or dispatch in this demo.</p>`:''}${r.status==='Quotation ready'?`<button class="btn primary" data-pharma="accept-quote" data-id="${esc(r.id)}">Accept demo quotation ↗</button>`:''}${r.orderId?`<a class="text-link" href="#/account?tab=orders">Order ${esc(r.orderId)} →</a>`:''}</article>`).join(''):'<div class="empty"><h2>No prescription requests yet.</h2><p>Submit a sample prescription to see its review and quote here.</p><a class="btn primary" href="#/prescription">Submit sample prescription</a></div>'}</section><section class="section"><div class="section-heading"><h2>Your consultation requests.</h2><a class="text-link" href="#/consult">Explore services ↗</a></div>${appointments.length?appointments.map(a=>`<article class="care-request panel"><div class="request-heading"><div><span class="eyebrow">${esc(a.id)}</span><h3>${esc(a.serviceName||'Consultation request')}</h3></div><span class="pill">${esc(a.status)}</span></div><p>${esc(a.date||'')} ${esc(a.time||'')} IST · Preferred slot</p><p class="small">${a.assignedClinician?'Assigned by demo team: '+esc(a.assignedClinician):'No clinician assigned yet.'}</p>${a.teamNote?`<div class="notice">${esc(a.teamNote)}</div>`:''}${a.meetingNote?`<p class="small">${esc(a.meetingNote)}</p>`:''}</article>`).join(''):'<div class="empty"><h2>No consultation requests yet.</h2><p>No consultation requests yet.</p><a class="btn primary" href="#/consult">Find a consultation service</a></div>'}</section>`}
function pharmacyHome(){const services=document.createElement('section');services.className='section pharmacy-service-block';services.innerHTML=`<div class="pharmacy-service-grid"><a href="#/medicines"><span class="service-3d blue">✚</span><div><h3>Find medicines</h3><p>Search by name or ingredient</p></div><b>↗</b></a><a href="#/compare"><span class="service-3d mint">⇄</span><div><h3>Compare prices</h3><p>View pack and unit prices</p></div><b>↗</b></a><a href="#/prescription"><span class="service-3d lilac">▤</span><div><h3>Upload a prescription</h3><p>Team review & personal quotation</p></div><b>↗</b></a><a href="#/consult"><span class="service-3d peach">♡</span><div><h3>Consult a doctor</h3><p>Request a consultation</p></div><b>↗</b></a></div>`;const hero=main.querySelector('.hero-poster');if(Store.state.settings.showServices)hero?.after(services);const wrap=main.querySelector('.wrap');if(Store.state.settings.showComparison){const section=document.createElement('section');section.className='section home-comparison';const result=PharmacyCore.compare(Store.state,'pantop-40');section.innerHTML=`<div class="section-heading"><div><span class="eyebrow">PRICE COMPARISON</span><h2>What does your medicine cost?</h2><p>Compare the same listed ingredient and strength, with pack sizes shown clearly.</p></div><a class="text-link" href="#/compare">Compare medicines ⇄</a></div>${result.base?`<div class="home-price-list"><div class="home-price-caption"><strong>${esc(result.base.ingredient)} ${esc(result.base.strength)}</strong><span>Illustrative catalogue prices</span></div>${result.matches.slice(0,3).map(p=>`<a class="home-price-row" href="#/product/${esc(p.id)}"><img src="${esc(p.image)}" alt="Sample pack" loading="lazy"><div><strong>${esc(p.name)}</strong><span>${p.packUnits} units · ${esc(p.dosageForm)}</span></div><div class="home-price-value"><b>${money(p.price)}</b><span>${pmoney(PharmacyCore.unitPrice(p))} / unit</span></div><span class="home-price-arrow" aria-hidden="true">→</span></a>`).join('')}</div>`:''}<p class="small">Illustrative prices only. Matching metadata does not confirm clinical interchangeability; ask your pharmacist or prescriber.</p>`;services.isConnected?services.after(section):wrap?.appendChild(section)}if(Store.state.settings.showOffers){const section=document.createElement('section');section.className='section';section.innerHTML=`<div class="section-heading"><div><h2>Offers & ways to save</h2><p>Sample offers and comparison tools.</p></div><a class="text-link" href="#/offers">All offers ↗</a></div><div class="offer-strip">${Store.state.offers.filter(o=>o.active).map(o=>`<a href="${esc(o.link)}"><span>${o.code?'%':'⇄'}</span><div><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p>${o.code?`<b>${esc(o.code)}</b>`:''}</div><i>↗</i></a>`).join('')}</div>`;wrap?.appendChild(section)}}
function pharmacyNavigation(){const nav=document.querySelector('.nav-inner');if(!nav)return;const all=document.createElement('div');all.className='store-departments';all.innerHTML=`<button class="department-toggle" id="department-toggle" aria-expanded="false" aria-controls="department-panel">☰ &nbsp; Shop departments <span>⌄</span></button><div class="department-panel" id="department-panel" hidden>${Store.state.categories.filter(c=>c.active).map(c=>`<a href="${c.id==='Medicines'?'#/medicines':'#/shop?category='+encodeURIComponent(c.id)}">${esc(c.name)} <span>↗</span></a>`).join('')}<a href="#/compare">Medicine comparison ⇄</a><a href="#/my-care">My Care & quotations ↗</a></div>`;nav.prepend(all);const link=document.createElement('a');link.href='#/my-care';link.className='care-nav-link';link.textContent='My Care & quotes';nav.appendChild(link);const menu=document.getElementById('mobile-menu');menu?.setAttribute('aria-label','Open pharmacy menu');const headerSearch=document.getElementById('search');if(headerSearch)headerSearch.placeholder='Search medicine, brand, ingredient or wellness…';}
render=function(reset=true){const {path,params}=route();if(['/medicines','/compare','/offers','/prescription','/consult','/my-care'].includes(path)){PRODUCTS=Store.state.products.filter(p=>p.active);CONFIG.whatsappNumber=Store.state.settings.whatsappNumber;main.innerHTML=path==='/medicines'?medCatalogue(params):path==='/compare'?comparePage(params):path==='/offers'?offersPage():path==='/prescription'?prescriptionPage(params):path==='/consult'?consultationPage():myCarePage();updateHeader();enhance();if(reset){window.scrollTo(0,0);main.focus({preventScroll:true})}document.title=({'/medicines':'Medicine shop','/compare':'Medicine comparison','/offers':'Offers','/prescription':'Prescription quotation','/consult':'Doctor consultation','/my-care':'My Care'}[path])+' — TrustedMeds';if(path==='/my-care')loadMyCare();rxFileData=null}else{pharmacyPreviousRender(reset);if(path==='/')pharmacyHome();if(path.startsWith('/product/')){const p=Store.state.products.find(p=>p.id===path.split('/')[2]);if(p?.medicine){const info=main.querySelector('.detail-meta');info?.insertAdjacentHTML('beforebegin',`<div class="medicine-detail-meta"><b>${esc(p.brand)} · ${esc(p.manufacturer)}</b><p>${esc(p.ingredient)} ${esc(p.strength)}<br>${esc(p.dosageForm)} · ${esc(p.release)} · ${esc(p.variant)}</p><span>${pmoney(PharmacyCore.unitPrice(p))} / unit · ${p.packUnits} units per sample pack</span><a class="btn block" href="#/compare?medicine=${p.id}">Compare brands & sample prices ⇄</a></div>`)}}if(path==='/account'){const panel=main.querySelector('.account-content,.login-card');panel?.insertAdjacentHTML('afterbegin','<a class="care-account-link" href="#/my-care">▤ &nbsp; Your prescription quotations & consultations <span>↗</span></a>')}}pharmacyNavigation()};
function medNavigate(key,value){const p=route().params;if(value)p.set(key,value);else p.delete(key);location.hash='/medicines?'+p.toString()}
document.addEventListener('click',async e=>{const department=e.target.closest('#department-toggle');if(department){const panel=document.getElementById('department-panel'),open=panel.hidden;panel.hidden=!open;department.setAttribute('aria-expanded',String(open));return}const b=e.target.closest('[data-pharma]');if(!b)return;const type=b.dataset.pharma;try{if(type==='consult-scroll'){e.preventDefault();document.getElementById('consult-services')?.scrollIntoView({behavior:'smooth',block:'start'})}if(type==='medicine-filter')medNavigate(b.dataset.filter,b.dataset.value);if(type==='book-consult')consultModal(b.dataset.id);if(type==='copy-coupon'){try{await navigator.clipboard.writeText(b.dataset.code);toast('Demo coupon copied: '+b.dataset.code)}catch{toast('Use coupon '+b.dataset.code+' at demo checkout.')}}if(type==='refresh-care'){await Store.refresh();loadMyCare()}if(type==='accept-quote'){b.disabled=true;const receipt=rxReceipts.find(r=>r.id===b.dataset.id),order=await Store.acceptPrescription(receipt);orders=[order,...orders].slice(0,50);save('orders',orders);toast('Demo quote accepted. Order '+order.id+' created.');loadMyCare()}}catch(error){toast(error.message);b.disabled=false}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='comparison-medicine')location.hash='/compare?medicine='+encodeURIComponent(t.value);if(t.id==='medicine-stock')medNavigate('stock',t.checked?'1':'');if(t.id==='medicine-sort')medNavigate('sort',t.value);if(t.id==='rx-sample-file'){rxFileData=null;const file=t.files[0],note=document.getElementById('rx-file-note'),preview=document.getElementById('rx-sample-preview');preview.hidden=true;if(!file)return;if(!['image/png','image/jpeg','application/pdf'].includes(file.type)||file.size>2*1024*1024){note.textContent='Choose JPG, PNG or PDF under 2 MB.';t.value='';return}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});rxFileData={name:file.name,mime:file.type,data};note.textContent=file.name+' · Sample only';if(file.type.startsWith('image/')){preview.src=data;preview.hidden=false}}catch{note.textContent='The sample file could not be read.'}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['medicine-search','comparison-search','pharmacy-rx-form','consult-request-form'].includes(f.id))return;e.preventDefault();if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f)),button=f.querySelector('button');if(f.id==='medicine-search'){location.hash='/medicines?q='+encodeURIComponent(values.q||'');return}if(f.id==='comparison-search'){const match=Store.state.products.find(p=>p.active&&p.ingredient&&[p.name,p.brand,p.ingredient].join(' ').toLowerCase().includes(String(values.q).toLowerCase()));location.hash='/compare?'+new URLSearchParams({q:values.q||'',...(match?{medicine:match.id}:{})});return}button.disabled=true;try{if(f.id==='pharmacy-rx-form'){if(!rxFileData)throw Error('Choose a sample prescription first.');const receipt=await Store.submitPrescription({patientAlias:values.patientAlias,notes:values.notes,sampleConfirmed:f.elements.sampleConfirmed.checked,document:rxFileData});rxReceipts.unshift(receipt);save('rx-receipts',rxReceipts);rxFileData=null;location.hash='/my-care';toast('Sample prescription submitted for team review.')}if(f.id==='consult-request-form'){const receipt=await Store.requestConsultation({serviceId:f.dataset.service,patientAlias:values.patientAlias,date:values.date,time:values.time,notes:values.notes,sampleConfirmed:f.elements.sampleConfirmed.checked});consultReceipts.unshift(receipt);save('consult-receipts',consultReceipts);document.getElementById('modal').close();location.hash='/my-care';toast('Demo consultation requested. Team confirmation is pending.')}}catch(error){toast(error.message)}finally{button.disabled=false}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const panel=document.getElementById('department-panel');if(panel){panel.hidden=true;document.getElementById('department-toggle')?.setAttribute('aria-expanded','false')}}});
render(false);

document.addEventListener('submit',e=>{if(e.target.id!=='header-search')return;e.preventDefault();e.stopImmediatePropagation();const q=document.getElementById('search').value.trim();const medicine=Store.state.products.some(p=>p.active&&p.medicine&&[p.name,p.brand,p.ingredient].join(' ').toLowerCase().includes(q.toLowerCase()));location.hash=(medicine?'#/medicines?q=':'#/shop?q=')+encodeURIComponent(q);},true);
